// Times sets number of times ingestRepository.UpsertPlate should be invoked
func (mmUpsertPlate *mIngestRepositoryMockUpsertPlate) Times(n uint64) *mIngestRepositoryMockUpsertPlate {
	if n == 0 {
		mmUpsertPlate.mock.t.Fatalf("Times of IngestRepositoryMock.UpsertPlate mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmUpsertPlate.expectedInvocations, n)
	mmUpsertPlate.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmUpsertPlate
}

func (mmUpsertPlate *mIngestRepositoryMockUpsertPlate) invocationsDone() bool {
	if len(mmUpsertPlate.expectations) == 0 && mmUpsertPlate.defaultExpectation == nil && mmUpsertPlate.mock.funcUpsertPlate == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmUpsertPlate.mock.afterUpsertPlateCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmUpsertPlate.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// UpsertPlate implements mm_usecase.ingestRepository
func (mmUpsertPlate *IngestRepositoryMock) UpsertPlate(ctx context.Context, tx db.Executor, o models.UpsertPlateOpts) (s1 string, err error) {
	mm_atomic.AddUint64(&mmUpsertPlate.beforeUpsertPlateCounter, 1)
	defer mm_atomic.AddUint64(&mmUpsertPlate.afterUpsertPlateCounter, 1)

	mmUpsertPlate.t.Helper()

	if mmUpsertPlate.inspectFuncUpsertPlate != nil {
		mmUpsertPlate.inspectFuncUpsertPlate(ctx, tx, o)
	}

	mm_params := IngestRepositoryMockUpsertPlateParams{ctx, tx, o}

	// Record call args
	mmUpsertPlate.UpsertPlateMock.mutex.Lock()
	mmUpsertPlate.UpsertPlateMock.callArgs = append(mmUpsertPlate.UpsertPlateMock.callArgs, &mm_params)
	mmUpsertPlate.UpsertPlateMock.mutex.Unlock()

	for _, e := range mmUpsertPlate.UpsertPlateMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.s1, e.results.err
		}
	}

	if mmUpsertPlate.UpsertPlateMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmUpsertPlate.UpsertPlateMock.defaultExpectation.Counter, 1)
		mm_want := mmUpsertPlate.UpsertPlateMock.defaultExpectation.params
		mm_want_ptrs := mmUpsertPlate.UpsertPlateMock.defaultExpectation.paramPtrs

		mm_got := IngestRepositoryMockUpsertPlateParams{ctx, tx, o}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmUpsertPlate.t.Errorf("IngestRepositoryMock.UpsertPlate got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpsertPlate.UpsertPlateMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.tx != nil && !minimock.Equal(*mm_want_ptrs.tx, mm_got.tx) {
				mmUpsertPlate.t.Errorf("IngestRepositoryMock.UpsertPlate got unexpected parameter tx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpsertPlate.UpsertPlateMock.defaultExpectation.expectationOrigins.originTx, *mm_want_ptrs.tx, mm_got.tx, minimock.Diff(*mm_want_ptrs.tx, mm_got.tx))
			}

			if mm_want_ptrs.o != nil && !minimock.Equal(*mm_want_ptrs.o, mm_got.o) {
				mmUpsertPlate.t.Errorf("IngestRepositoryMock.UpsertPlate got unexpected parameter o, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpsertPlate.UpsertPlateMock.defaultExpectation.expectationOrigins.originO, *mm_want_ptrs.o, mm_got.o, minimock.Diff(*mm_want_ptrs.o, mm_got.o))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmUpsertPlate.t.Errorf("IngestRepositoryMock.UpsertPlate got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmUpsertPlate.UpsertPlateMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmUpsertPlate.UpsertPlateMock.defaultExpectation.results
		if mm_results == nil {
			mmUpsertPlate.t.Fatal("No results are set for the IngestRepositoryMock.UpsertPlate")
		}
		return (*mm_results).s1, (*mm_results).err
	}
	if mmUpsertPlate.funcUpsertPlate != nil {
		return mmUpsertPlate.funcUpsertPlate(ctx, tx, o)
	}
	mmUpsertPlate.t.Fatalf("Unexpected call to IngestRepositoryMock.UpsertPlate. %v %v %v", ctx, tx, o)
	return
}

// UpsertPlateAfterCounter returns a count of finished IngestRepositoryMock.UpsertPlate invocations
func (mmUpsertPlate *IngestRepositoryMock) UpsertPlateAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmUpsertPlate.afterUpsertPlateCounter)
}

// UpsertPlateBeforeCounter returns a count of IngestRepositoryMock.UpsertPlate invocations
func (mmUpsertPlate *IngestRepositoryMock) UpsertPlateBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmUpsertPlate.beforeUpsertPlateCounter)
}

// Calls returns a list of arguments used in each call to IngestRepositoryMock.UpsertPlate.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmUpsertPlate *mIngestRepositoryMockUpsertPlate) Calls() []*IngestRepositoryMockUpsertPlateParams {
	mmUpsertPlate.mutex.RLock()

	argCopy := make([]*IngestRepositoryMockUpsertPlateParams, len(mmUpsertPlate.callArgs))
	copy(argCopy, mmUpsertPlate.callArgs)

	mmUpsertPlate.mutex.RUnlock()

	return argCopy
}

// MinimockUpsertPlateDone returns true if the count of the UpsertPlate invocations corresponds
// the number of defined expectations
func (m *IngestRepositoryMock) MinimockUpsertPlateDone() bool {
	if m.UpsertPlateMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.UpsertPlateMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.UpsertPlateMock.invocationsDone()
}

// MinimockUpsertPlateInspect logs each unmet expectation
func (m *IngestRepositoryMock) MinimockUpsertPlateInspect() {
	for _, e := range m.UpsertPlateMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to IngestRepositoryMock.UpsertPlate at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUpsertPlateCounter := mm_atomic.LoadUint64(&m.afterUpsertPlateCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UpsertPlateMock.defaultExpectation != nil && afterUpsertPlateCounter < 1 {
		if m.UpsertPlateMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to IngestRepositoryMock.UpsertPlate at\n%s", m.UpsertPlateMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to IngestRepositoryMock.UpsertPlate at\n%s with params: %#v", m.UpsertPlateMock.defaultExpectation.expectationOrigins.origin, *m.UpsertPlateMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUpsertPlate != nil && afterUpsertPlateCounter < 1 {
		m.t.Errorf("Expected call to IngestRepositoryMock.UpsertPlate at\n%s", m.funcUpsertPlateOrigin)
	}

	if !m.UpsertPlateMock.invocationsDone() && afterUpsertPlateCounter > 0 {
		m.t.Errorf("Expected %d calls to IngestRepositoryMock.UpsertPlate at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UpsertPlateMock.expectedInvocations), m.UpsertPlateMock.expectedInvocationsOrigin, afterUpsertPlateCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *IngestRepositoryMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockCreateSightingInspect()

			m.MinimockUpsertPlateInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *IngestRepositoryMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *IngestRepositoryMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockCreateSightingDone() &&
		m.MinimockUpsertPlateDone()
}
